33	/// Default wall-clock timeout for a command (matches the SMA-328 `BashTool`).
34	pub const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);
35	/// Default per-stream output cap, in bytes (1 MiB).
36	pub const DEFAULT_MAX_OUTPUT: usize = 1 << 20;
