38	/// A backend that runs one shell command under some containment tier.
39	///
40	/// Object-safe and not generic over the agent context, so one value is shared as
41	/// `Arc<dyn ExecutionBackend>` across agents of any context type. Swapping the
42	/// backend needs no change to [`crate::BashTool`] or agent code.
43	#[async_trait]
44	pub trait ExecutionBackend: Send + Sync {
45	    /// Run `req.command` to completion under this backend's containment.
46	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError>;
47	
48	    /// What this backend actually enforces — surfaced in docs, the model-facing
49	    /// tool description, and traces. Describes *containment*, not approval.
50	    fn guarantees(&self) -> SandboxGuarantees;
51	}
52	
53	/// A request to run one shell command. `#[non_exhaustive]` so per-call knobs
54	/// (stdin, env overrides) can be added later without a breaking change.
55	#[derive(Debug, Clone)]
56	#[non_exhaustive]
57	pub struct ExecRequest {
58	    /// The shell command (`sh -c <command>` on unix, `cmd /C` on Windows).
59	    pub command: String,
60	}
61	
62	impl ExecRequest {
63	    /// Build a request from a command string.
64	    pub fn new(command: impl Into<String>) -> Self {
65	        Self {
66	            command: command.into(),
67	        }
68	    }
69	}
70	
71	/// The captured result of one command run. Non-zero exit, timeout, and
72	/// truncation are *normal results* the model inspects — never errors.
73	#[derive(Debug, Clone)]
74	#[non_exhaustive]
75	pub struct ExecOutput {
76	    /// Captured stdout (lossy UTF-8, truncated at the backend's output cap).
77	    pub stdout: String,
78	    /// Captured stderr (lossy UTF-8, truncated at the backend's output cap).
79	    pub stderr: String,
80	    /// Process exit code, or `None` if killed by signal / timeout.
81	    pub exit_code: Option<i32>,
82	    /// Whether the command was killed because it exceeded the timeout.
83	    pub timed_out: bool,
84	    /// Whether either stream was truncated at the output cap.
85	    pub truncated: bool,
86	}
87	
88	impl ExecOutput {
89	    /// Construct an `ExecOutput` from all fields.
90	    pub fn new(
91	        stdout: String,
92	        stderr: String,
93	        exit_code: Option<i32>,
94	        timed_out: bool,
95	        truncated: bool,
96	    ) -> Self {
97	        Self {
98	            stdout,
99	            stderr,
100	            exit_code,
101	            timed_out,
102	            truncated,
103	        }
104	    }
105	}
