107	/// The isolation level enforced on one axis (filesystem / network / syscalls).
108	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
109	#[non_exhaustive]
110	pub enum Isolation {
111	    /// No OS enforcement — the command has the same access this process does.
112	    None,
113	    /// Enforced by an OS kernel mechanism (Landlock / seccomp-bpf).
114	    OsKernel,
115	}
