117	/// What a backend enforces, surfaced to docs / traces / the tool description.
118	#[derive(Debug, Clone)]
119	#[non_exhaustive]
120	pub struct SandboxGuarantees {
121	    /// Filesystem containment.
122	    pub filesystem: Isolation,
123	    /// Network containment.
124	    pub network: Isolation,
125	    /// Syscall containment.
126	    pub syscalls: Isolation,
127	    /// Short human label, e.g. `"host (no containment)"`.
128	    pub label: &'static str,
129	}
