148	/// Resource limits applied to a command via `setrlimit` (unix). Each `None`
149	/// leaves the inherited limit. See `HostBackend` for the default policy.
150	///
151	/// Not `#[non_exhaustive]`: this is user-built config (struct-literal
152	/// construction from consumer code and integration tests); adding a field later
153	/// is an accepted 0.x breaking change.
154	#[derive(Debug, Clone, Default)]
155	pub struct ResourceLimits {
156	    /// `RLIMIT_CPU` — CPU seconds.
157	    pub cpu_seconds: Option<u64>,
158	    /// `RLIMIT_FSIZE` — max bytes a single file write may reach.
159	    pub file_size_bytes: Option<u64>,
160	    /// `RLIMIT_AS` — virtual address-space cap. Approximate; off by default
161	    /// because it spuriously kills threaded/`mmap`-heavy programs.
162	    pub address_space_bytes: Option<u64>,
163	}
164	
165	/// Internal config every backend shares; consumed by [`spawn_capped`].
166	pub(crate) struct ExecConfig {
167	    pub(crate) cwd: PathBuf,
168	    pub(crate) env_allowlist: Vec<String>,
169	    pub(crate) timeout: Duration,
170	    pub(crate) max_output_bytes: usize,
171	}
