173	use std::process::Stdio;
174	use tokio::io::AsyncReadExt;
175	
176	/// Grace period for reaping a killed process and draining its pipes.
177	const GRACE: Duration = Duration::from_secs(5);
178	
179	/// Spawn `command` under `cfg`, draining stdout/stderr concurrently, killing the
180	/// whole process group on timeout. `prefix`, when non-empty, is prepended as
181	/// `program [args...]` ahead of `sh -c <command>` (used by the macOS Seatbelt
182	/// backend to wrap the shell in `sandbox-exec`). `configure_child` runs in the
183	/// **parent** to install backend-specific `pre_exec` hooks before spawn.
184	pub(crate) async fn spawn_capped(
185	    cfg: &ExecConfig,
186	    prefix: &[OsString],
187	    command: &str,
188	    configure_child: impl FnOnce(&mut tokio::process::Command),
189	) -> Result<ExecOutput, ToolError> {
190	    let mut cmd = build_command(prefix, command);
191	    cmd.current_dir(&cfg.cwd)
192	        .env_clear()
193	        .stdin(Stdio::null())
194	        .stdout(Stdio::piped())
195	        .stderr(Stdio::piped());
196	    for name in &cfg.env_allowlist {
197	        if let Ok(val) = std::env::var(name) {
198	            cmd.env(name, val);
199	        }
200	    }
201	    #[cfg(unix)]
202	    {
203	        // New process group so a timeout can kill the whole subtree.
204	        cmd.process_group(0);
205	    }
206	    configure_child(&mut cmd);
207	
208	    let mut child = cmd
209	        .spawn()
210	        .map_err(|e| ToolError::Other(anyhow::anyhow!("failed to spawn shell: {e}")))?;
211	
212	    #[cfg(unix)]
213	    let pgid = child.id();
214	
215	    let stdout_pipe = child.stdout.take().expect("piped stdout");
216	    let stderr_pipe = child.stderr.take().expect("piped stderr");
217	
218	    let cap = cfg.max_output_bytes;
219	    let out_handle = tokio::spawn(read_capped(stdout_pipe, cap));
220	    let err_handle = tokio::spawn(read_capped(stderr_pipe, cap));
221	
222	    let mut timed_out = false;
223	    let exit_code: Option<i32>;
224	    match tokio::time::timeout(cfg.timeout, child.wait()).await {
225	        Ok(status) => {
226	            exit_code = status.map_err(|e| ToolError::Other(e.into()))?.code();
227	        }
228	        Err(_) => {
229	            timed_out = true;
230	            #[cfg(unix)]
231	            {
232	                if let Some(pid) = pgid {
233	                    // SAFETY: pid < 4_194_304 on supported platforms, so the cast
234	                    // and negation are valid; ESRCH (group already gone) is benign.
235	                    let _ = unsafe { libc::kill(-(pid as i32), libc::SIGKILL) };
236	                }
237	            }
238	            #[cfg(not(unix))]
239	            {
240	                let _ = child.start_kill();
241	            }
242	            exit_code = match tokio::time::timeout(GRACE, child.wait()).await {
243	                Ok(Ok(status)) => status.code(),
244	                _ => None,
245	            };
246	        }
247	    }
248	
249	    let ((stdout, out_trunc), (stderr, err_trunc)) =
250	        tokio::join!(join_reader(out_handle), join_reader(err_handle));
251	
252	    Ok(ExecOutput {
253	        stdout,
254	        stderr,
255	        exit_code,
256	        timed_out,
257	        truncated: out_trunc || err_trunc,
258	    })
259	}
260	
261	/// Build the platform shell command without yet setting cwd/env. `prefix`, when
262	/// non-empty, is prepended as `program [args...]` before `sh -c <command>` — used
263	/// by the macOS Seatbelt backend to wrap the shell in `sandbox-exec`. Empty for
264	/// the host and Linux backends.
265	fn build_command(prefix: &[OsString], command: &str) -> tokio::process::Command {
266	    #[cfg(unix)]
267	    {
268	        match prefix.split_first() {
269	            Some((program, rest)) => {
270	                let mut c = tokio::process::Command::new(program);
271	                c.args(rest).arg("sh").arg("-c").arg(command);
272	                c
273	            }
274	            None => {
275	                let mut c = tokio::process::Command::new("sh");
276	                c.arg("-c").arg(command);
277	                c
278	            }
279	        }
280	    }
281	    #[cfg(windows)]
282	    {
283	        // `prefix` is always empty on Windows; bind it to avoid `unused_variables`
284	        // under `-D warnings` (clippy runs on ubuntu; Windows is signal-only).
285	        let _ = prefix;
286	        let mut c = tokio::process::Command::new("cmd");
287	        c.arg("/C").arg(command);
288	        c
289	    }
290	}
291	
292	async fn join_reader(handle: tokio::task::JoinHandle<(String, bool)>) -> (String, bool) {
293	    let abort = handle.abort_handle();
294	    match tokio::time::timeout(GRACE, handle).await {
295	        Ok(Ok(captured)) => captured,
296	        _ => {
297	            abort.abort();
298	            (String::new(), false)
299	        }
300	    }
301	}
302	
303	async fn read_capped<R>(pipe: R, cap: usize) -> (String, bool)
304	where
305	    R: tokio::io::AsyncRead + Unpin + Send + 'static,
306	{
307	    let mut buf = Vec::new();
308	    let _ = pipe.take((cap as u64) + 1).read_to_end(&mut buf).await;
309	    let truncated = buf.len() > cap;
310	    buf.truncate(cap);
311	    (String::from_utf8_lossy(&buf).into_owned(), truncated)
312	}
313	
314	/// Apply `limits` to the current process via `setrlimit`. Async-signal-safe
315	/// (only `setrlimit` syscalls, no allocation) so it is callable from `pre_exec`.
316	#[cfg(unix)]
317	pub(crate) fn apply_rlimits(limits: &ResourceLimits) -> std::io::Result<()> {
318	    // SAFETY: setrlimit with a stack-allocated rlimit is async-signal-safe.
319	    unsafe {
320	        // The resource arg's type differs per target (`c_int` on macOS/BSD/musl,
321	        // `__rlimit_resource_t` on Linux glibc), so it is inferred from the
322	        // platform's `RLIMIT_*` constants rather than fixed to one type.
323	        let set = |res, val: u64| -> std::io::Result<()> {
324	            let rl = libc::rlimit {
325	                rlim_cur: val as libc::rlim_t,
326	                rlim_max: val as libc::rlim_t,
327	            };
328	            if libc::setrlimit(res, &rl) != 0 {
329	                return Err(std::io::Error::last_os_error());
330	            }
331	            Ok(())
332	        };
333	        if let Some(s) = limits.cpu_seconds {
334	            set(libc::RLIMIT_CPU, s)?;
335	        }
336	        if let Some(b) = limits.file_size_bytes {
337	            set(libc::RLIMIT_FSIZE, b)?;
338	        }
339	        if let Some(b) = limits.address_space_bytes {
340	            set(libc::RLIMIT_AS, b)?;
341	        }
342	    }
343	    Ok(())
344	}
