1	//! [`OsSandboxBackend`] — OS-enforced Bash containment on Linux via Landlock
2	//! (filesystem) + seccomp-bpf (syscalls / network). Fail-closed: `build()` errors
3	//! if the kernel cannot enforce the requested isolation.
4	
5	use std::collections::BTreeMap;
6	use std::path::PathBuf;
7	use std::sync::Arc;
8	use std::time::Duration;
9	
10	use async_trait::async_trait;
11	use landlock::{
12	    path_beneath_rules, Access, AccessFs, CompatLevel, Compatible, Ruleset, RulesetAttr,
13	    RulesetCreatedAttr, RulesetStatus, ABI,
14	};
15	use paigasus_helikon_core::ToolError;
16	use seccompiler::{
17	    apply_filter, BpfProgram, SeccompAction, SeccompCmpArgLen, SeccompCmpOp, SeccompCondition,
18	    SeccompFilter, SeccompRule, TargetArch,
19	};
20	
21	use super::{
22	    spawn_capped, ExecConfig, ExecOutput, ExecRequest, ExecutionBackend, Isolation, ResourceLimits,
23	    SandboxGuarantees, DEFAULT_MAX_OUTPUT, DEFAULT_TIMEOUT,
24	};
25	use crate::sandbox::Sandbox;
26	
27	/// Landlock ABI floor we require for filesystem containment (kernel ≥ 5.13).
28	const LANDLOCK_ABI: ABI = ABI::V1;
29	
30	/// Target arch for the seccomp BPF. The `os_sandbox` module is gated to these two
31	/// arches (see `super::os_sandbox` cfg), so exactly one of these is compiled.
32	#[cfg(target_arch = "x86_64")]
33	const SECCOMP_ARCH: TargetArch = TargetArch::x86_64;
34	#[cfg(target_arch = "aarch64")]
35	const SECCOMP_ARCH: TargetArch = TargetArch::aarch64;
36	
37	/// Construction failures for [`OsSandboxBackend`]. Distinct from
38	/// `ToolError::Denied` (an in-`run` refusal) and from `SandboxError`.
39	#[derive(Debug, thiserror::Error)]
40	#[non_exhaustive]
41	pub enum OsSandboxError {
42	    /// The kernel cannot enforce Landlock at the required ABI.
43	    #[error("OS sandbox unavailable: {0}")]
44	    Unsupported(String),
45	}
46	
47	/// Builder for [`OsSandboxBackend`].
48	pub struct OsSandboxBackendBuilder {
49	    sandbox: Sandbox,
50	    timeout: Duration,
51	    env_allowlist: Vec<String>,
52	    max_output_bytes: usize,
53	    limits: ResourceLimits,
54	    allow_network: bool,
55	    read_paths: Vec<PathBuf>,
56	}
57	
58	impl OsSandboxBackendBuilder {
59	    /// Wall-clock timeout before the process group is killed (default 30s).
60	    pub fn timeout(mut self, timeout: Duration) -> Self {
61	        self.timeout = timeout;
62	        self
63	    }
64	    /// Env var names to pass through (REPLACES the default `["PATH","HOME"]`).
65	    pub fn env_allowlist<I, S>(mut self, names: I) -> Self
66	    where
67	        I: IntoIterator<Item = S>,
68	        S: Into<String>,
69	    {
70	        self.env_allowlist = names.into_iter().map(Into::into).collect();
71	        self
72	    }
73	    /// Truncate captured stdout/stderr to this many bytes each (default 1 MiB).
74	    pub fn max_output_bytes(mut self, n: usize) -> Self {
75	        self.max_output_bytes = n;
76	        self
77	    }
78	    /// Override resource limits applied inside the jail.
79	    pub fn rlimits(mut self, limits: ResourceLimits) -> Self {
80	        self.limits = limits;
81	        self
82	    }
83	    /// Allow outbound network (default: deny all IP egress).
84	    pub fn allow_network(mut self, allow: bool) -> Self {
85	        self.allow_network = allow;
86	        self
87	    }
88	    /// Extra read-only path exceptions beyond the default system set.
89	    pub fn read_paths<I, P>(mut self, paths: I) -> Self
90	    where
91	        I: IntoIterator<Item = P>,
92	        P: Into<PathBuf>,
93	    {
94	        self.read_paths = paths.into_iter().map(Into::into).collect();
95	        self
96	    }
97	
98	    /// Finish building. **Fail-closed:** returns `Err` if Landlock cannot be
99	    /// enforced at the required ABI (v1; kernel ≥ 5.13) on this host.
100	    pub fn build(self) -> Result<Arc<dyn ExecutionBackend>, OsSandboxError> {
101	        probe_landlock()?;
102	        Ok(Arc::new(OsSandboxBackend {
103	            cfg: ExecConfig {
104	                cwd: self.sandbox.root().to_path_buf(),
105	                env_allowlist: self.env_allowlist,
106	                timeout: self.timeout,
107	                max_output_bytes: self.max_output_bytes,
108	            },
109	            limits: self.limits,
110	            allow_network: self.allow_network,
111	            root: self.sandbox.root().to_path_buf(),
112	            read_paths: self.read_paths,
113	        }))
114	    }
115	}
116	
117	/// Probe Landlock support without restricting the current process: create a
118	/// ruleset fd under a hard-requirement compat level and drop it.
119	fn probe_landlock() -> Result<(), OsSandboxError> {
120	    Ruleset::default()
121	        .set_compatibility(CompatLevel::HardRequirement)
122	        .handle_access(AccessFs::from_all(LANDLOCK_ABI))
123	        .and_then(|r| r.create())
124	        .map(|_created| ())
125	        .map_err(|e| OsSandboxError::Unsupported(e.to_string()))
126	}
