128	/// Read-only system paths a shell + common tools need. (`/usr/sbin` is covered
129	/// by `/usr`; `/sbin` is listed for distros that have not usr-merged it.)
130	const SYSTEM_RO: &[&str] = &["/usr", "/bin", "/sbin", "/lib", "/lib64", "/etc"];
131	
132	/// Build (in the parent) a Landlock ruleset: read+write under the sandbox root,
133	/// read+exec for the system paths and any extra `read_paths`.
134	fn build_ruleset(
135	    root: &std::path::Path,
136	    read_paths: &[PathBuf],
137	) -> Result<landlock::RulesetCreated, landlock::RulesetError> {
138	    let abi = LANDLOCK_ABI;
139	    let ro: Vec<PathBuf> = SYSTEM_RO
140	        .iter()
141	        .map(PathBuf::from)
142	        .chain(read_paths.iter().cloned())
143	        .filter(|p| p.exists())
144	        .collect();
145	    Ruleset::default()
146	        .set_compatibility(CompatLevel::HardRequirement)
147	        .handle_access(AccessFs::from_all(abi))?
148	        .create()?
149	        .add_rules(path_beneath_rules(&ro, AccessFs::from_read(abi)))?
150	        .add_rules(path_beneath_rules([root], AccessFs::from_all(abi)))
151	}
