153	/// Compile (in the parent) a seccomp filter: allow by default, return EPERM for a
154	/// dangerous syscall set; when `allow_network` is false also EPERM `socket()` for
155	/// `AF_INET`/`AF_INET6` (`AF_UNIX` stays allowed).
156	fn build_seccomp(allow_network: bool) -> Result<BpfProgram, ToolError> {
157	    // The `backend` constructors (`SeccompCondition/Rule/Filter::new`, the
158	    // `BpfProgram` `TryFrom`) all surface `seccompiler::BackendError`, NOT the
159	    // top-level `seccompiler::Error` (that one is for `apply_filter`).
160	    let err = |e: seccompiler::BackendError| ToolError::Other(anyhow::anyhow!("seccomp: {e}"));
161	    let mut rules: BTreeMap<i64, Vec<SeccompRule>> = BTreeMap::new();
162	
163	    // Always-deny dangerous syscalls (empty rule vec = match regardless of args).
164	    for sc in [
165	        libc::SYS_ptrace,
166	        libc::SYS_mount,
167	        libc::SYS_umount2,
168	        libc::SYS_pivot_root,
169	        libc::SYS_chroot,
170	        libc::SYS_setns,
171	        libc::SYS_unshare,
172	        libc::SYS_kexec_load,
173	        libc::SYS_bpf,
174	        libc::SYS_perf_event_open,
175	    ] {
176	        rules.insert(sc, vec![]);
177	    }
178	
179	    if !allow_network {
180	        // Match `socket(family, ..)` for AF_INET / AF_INET6 (arg0); AF_UNIX is
181	        // left allowed so local IPC and `/dev/log`-style sockets keep working.
182	        // x86_64/aarch64 use the direct `socket` syscall, so this is the egress
183	        // chokepoint. (The x32 ABI ORs a bit into the syscall number and would
184	        // slip past, but standard amd64 userland — including CI — ships no x32
185	        // binaries, so it is out of scope.)
186	        let af = |family: u64| -> Result<SeccompRule, ToolError> {
187	            SeccompRule::new(vec![SeccompCondition::new(
188	                0,
189	                SeccompCmpArgLen::Dword,
190	                SeccompCmpOp::Eq,
191	                family,
192	            )
193	            .map_err(err)?])
194	            .map_err(err)
195	        };
196	        rules.insert(
197	            libc::SYS_socket,
198	            vec![af(libc::AF_INET as u64)?, af(libc::AF_INET6 as u64)?],
199	        );
200	    }
201	
202	    let filter = SeccompFilter::new(
203	        rules,
204	        SeccompAction::Allow,                     // default: allow
205	        SeccompAction::Errno(libc::EPERM as u32), // on match: EPERM
206	        SECCOMP_ARCH,
207	    )
208	    .map_err(err)?;
209	    filter.try_into().map_err(err)
210	}
