221	impl OsSandboxBackend {
222	    /// Start building over `sandbox` (read+write root; default deny-network).
223	    pub fn builder(sandbox: Sandbox) -> OsSandboxBackendBuilder {
224	        OsSandboxBackendBuilder {
225	            sandbox,
226	            timeout: DEFAULT_TIMEOUT,
227	            env_allowlist: vec!["PATH".to_owned(), "HOME".to_owned()],
228	            max_output_bytes: DEFAULT_MAX_OUTPUT,
229	            limits: ResourceLimits::default(),
230	            allow_network: false,
231	            read_paths: Vec::new(),
232	        }
