236	#[async_trait]
237	impl ExecutionBackend for OsSandboxBackend {
238	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError> {
239	        let limits = self.limits.clone();
240	        // Built in the PARENT (allocations are safe here, not in the child).
241	        let ruleset = build_ruleset(&self.root, &self.read_paths)
242	            .map_err(|e| ToolError::Other(anyhow::anyhow!("landlock ruleset: {e}")))?;
243	        let mut ruleset = Some(ruleset);
244	        // Compile the seccomp BPF in the PARENT too (BTreeMap/Vec allocation is
245	        // not async-signal-safe and must not happen in the forked child).
246	        let seccomp = build_seccomp(self.allow_network)?;
247	
248	        spawn_capped(&self.cfg, &[], &req.command, move |cmd| {
249	            // SAFETY: the closure runs in the forked child before exec, so it does
250	            // only async-signal-safe work — no heap allocation, no locks: the
251	            // `setrlimit` syscalls in `apply_rlimits`, then Landlock's
252	            // `restrict_self` (`prctl(PR_SET_NO_NEW_PRIVS)` + `landlock_restrict_self`
253	            // on an already-created ruleset fd, plus a small stack struct), then
254	            // `apply_filter` (a `prctl(PR_SET_SECCOMP)` syscall over the pre-compiled
255	            // BPF). The `RulesetCreated` and `BpfProgram` are built in the parent and
256	            // moved in; the ruleset is taken via `Option::take` so it applies once.
257	            unsafe {
258	                cmd.pre_exec(move || {
259	                    super::apply_rlimits(&limits)?;
260	                    if let Some(rs) = ruleset.take() {
261	                        let status = rs
262	                            .restrict_self()
263	                            .map_err(|e| std::io::Error::other(e.to_string()))?;
264	                        // Fail-closed: accept only full enforcement. Anything less
265	                        // (a future ABI making Partial reachable) aborts the exec
266	                        // rather than running under weaker containment than claimed.
267	                        if status.ruleset != RulesetStatus::FullyEnforced {
268	                            return Err(std::io::Error::other("landlock not fully enforced"));
269	                        }
270	                    }
271	                    // Applied after Landlock. An unprivileged seccomp install needs
272	                    // PR_SET_NO_NEW_PRIVS, which `restrict_self` sets — though
273	                    // `apply_filter` also sets it itself, so this is not a strict
274	                    // seccomp prerequisite; we order Landlock first for its own
275	                    // semantics.
276	                    apply_filter(&seccomp).map_err(|e| std::io::Error::other(e.to_string()))?;
277	                    Ok(())
278	                });
279	            }
280	        })
281	        .await
282	    }
283	
284	    fn guarantees(&self) -> SandboxGuarantees {
285	        SandboxGuarantees {
286	            filesystem: Isolation::OsKernel,
287	            network: if self.allow_network {
288	                Isolation::None
289	            } else {
290	                Isolation::OsKernel
291	            },
292	            syscalls: Isolation::OsKernel,
293	            label: "os-sandbox (landlock+seccomp)",
294	        }
295	    }
296	}
