1	//! Private HTTP helpers shared by the web tools: the `reqwest::Client` builder,
2	//! host allow/deny matching, and the SSRF IP classifier.
3	
4	use std::net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr};
5	use std::sync::Arc;
6	use std::time::Duration;
7	
8	use paigasus_helikon_core::ToolError;
9	use reqwest::dns::{Addrs, Name, Resolve, Resolving};
10	
11	/// Build a `reqwest::Client` with a fixed user-agent and timeout. When
12	/// `follow_redirects` is false the client never auto-redirects (WebFetch drives
13	/// redirects itself so it can re-run the SSRF check on every hop). When
14	/// `dns_guard` is `Some(allow_private)`, a [`GuardedResolver`] is installed so
15	/// connect-time DNS results are validated through [`ip_blocked`] — pinning the
16	/// connection to vetted IPs and closing the DNS-rebinding TOCTOU. `None` uses
17	/// the default resolver (search backends, which hit fixed public API hosts).
18	pub(crate) fn build_client(
19	    user_agent: &str,
20	    timeout: Duration,
21	    follow_redirects: bool,
22	    dns_guard: Option<bool>,
23	) -> reqwest::Result<reqwest::Client> {
24	    let redirect = if follow_redirects {
25	        reqwest::redirect::Policy::default()
26	    } else {
27	        reqwest::redirect::Policy::none()
28	    };
29	    let mut builder = reqwest::Client::builder()
30	        .user_agent(user_agent.to_owned())
31	        .timeout(timeout)
32	        .redirect(redirect);
33	    if let Some(allow_private) = dns_guard {
34	        builder = builder.dns_resolver(Arc::new(GuardedResolver { allow_private }));
35	    }
36	    builder.build()
37	}
38	
39	/// A `reqwest` DNS resolver that drops resolved addresses failing [`ip_blocked`]
40	/// (unless `allow_private`), so the connection is pinned to validated IPs. This
41	/// is the connect-time half of the SSRF guard: it closes the rebinding window
42	/// between the pre-flight `ssrf_check` and reqwest's own resolution. Numeric-IP
43	/// hosts never reach a resolver — they are covered by the literal-IP branch of
44	/// [`ssrf_check`].
45	struct GuardedResolver {
46	    allow_private: bool,
47	}
48	
49	impl Resolve for GuardedResolver {
50	    fn resolve(&self, name: Name) -> Resolving {
51	        let allow_private = self.allow_private;
52	        Box::pin(async move {
53	            let host = name.as_str().to_owned();
54	            let resolved = tokio::net::lookup_host((host.as_str(), 0)).await?;
55	            let addrs: Vec<SocketAddr> = if allow_private {
56	                resolved.collect()
57	            } else {
58	                resolved.filter(|a| !ip_blocked(a.ip())).collect()
59	            };
60	            if addrs.is_empty() {
61	                let err: Box<dyn std::error::Error + Send + Sync> =
62	                    format!("no allowed addresses resolved for `{host}` (blocked by SSRF guard)")
63	                        .into();
64	                return Err(err);
65	            }
66	            let iter: Addrs = Box::new(addrs.into_iter());
67	            Ok(iter)
68	        })
69	    }
70	}
71	
72	/// `true` if `host` is permitted by the allow/deny lists. A list entry matches
73	/// when `host` equals it or is a sub-domain of it (case-insensitive). A deny
74	/// match always refuses; with an allow-list set, only matching hosts pass.
75	pub(crate) fn host_allowed(host: &str, allow: Option<&[String]>, deny: &[String]) -> bool {
76	    let host = host.trim_end_matches('.').to_ascii_lowercase();
77	    let matches = |entry: &String| {
78	        let e = entry.trim_end_matches('.').to_ascii_lowercase();
79	        host == e || host.ends_with(&format!(".{e}"))
80	    };
81	    if deny.iter().any(matches) {
82	        return false;
83	    }
84	    match allow {
85	        Some(list) => list.iter().any(matches),
86	        None => true,
87	    }
88	}
89	
90	/// `true` if `ip` is in a range the SSRF guard refuses: loopback, RFC1918
91	/// private, link-local (incl. `169.254.169.254`), CGNAT, IPv6 ULA, or
92	/// unspecified. v4-mapped v6 addresses are unwrapped and re-checked as v4.
93	pub(crate) fn ip_blocked(ip: IpAddr) -> bool {
94	    match ip {
95	        IpAddr::V4(v4) => v4_blocked(v4),
96	        IpAddr::V6(v6) => {
97	            // v6-specific ranges first, so `::1` / `::` are caught before the
98	            // v4 unwrap (`to_ipv4()` would map `::1` to the non-blocked
99	            // `0.0.0.1`).
100	            if v6.is_loopback()
101	                || v6.is_unspecified()
102	                || v6.is_multicast()
103	                || is_ula(v6)
104	                || is_v6_link_local(v6)
105	                || is_v6_documentation(v6)
106	            {
107	                return true;
108	            }
109	            // Unwrap both `::ffff:a.b.c.d` (mapped) and the deprecated
110	            // `::a.b.c.d` (compatible) and classify the embedded v4.
111	            if let Some(v4) = v6.to_ipv4_mapped().or_else(|| v6.to_ipv4()) {
112	                return v4_blocked(v4);
113	            }
114	            false
115	        }
116	    }
117	}
118	
119	fn v4_blocked(ip: Ipv4Addr) -> bool {
120	    ip.is_loopback()
121	        || ip.is_private()
122	        || ip.is_link_local()
123	        || ip.is_unspecified()
124	        || ip.is_broadcast()
125	        || ip.is_documentation()
126	        || ip.is_multicast()
127	        || is_cgnat(ip)
128	        || is_benchmarking_v4(ip)
129	        || is_reserved_future_v4(ip)
130	}
131	
132	/// `100.64.0.0/10` (RFC 6598 carrier-grade NAT). `std`'s predicate is unstable.
133	fn is_cgnat(ip: Ipv4Addr) -> bool {
134	    let o = ip.octets();
135	    o[0] == 100 && (64..=127).contains(&o[1])
136	}
137	
138	/// `198.18.0.0/15` (RFC 2544 benchmarking). `std`'s predicate is unstable.
139	fn is_benchmarking_v4(ip: Ipv4Addr) -> bool {
140	    let o = ip.octets();
141	    o[0] == 198 && (18..=19).contains(&o[1])
142	}
143	
144	/// `240.0.0.0/4` (RFC 1112 reserved-for-future-use; `255.255.255.255` is also
145	/// caught by `is_broadcast`). `std`'s predicate is unstable.
146	fn is_reserved_future_v4(ip: Ipv4Addr) -> bool {
147	    ip.octets()[0] >= 240
148	}
149	
150	/// `2001:db8::/32` (RFC 3849 documentation). `std`'s predicate is unstable.
151	fn is_v6_documentation(ip: Ipv6Addr) -> bool {
152	    let s = ip.segments();
153	    s[0] == 0x2001 && s[1] == 0x0db8
154	}
155	
156	/// `fc00::/7` (RFC 4193 unique-local). `std`'s predicate is unstable.
157	fn is_ula(ip: Ipv6Addr) -> bool {
158	    (ip.segments()[0] & 0xfe00) == 0xfc00
159	}
160	
161	/// `fe80::/10` (link-local). `std`'s predicate is unstable.
162	fn is_v6_link_local(ip: Ipv6Addr) -> bool {
163	    (ip.segments()[0] & 0xffc0) == 0xfe80
164	}
165	
166	/// SSRF guard: refuse a URL whose host is, or resolves to, a blocked IP. A
167	/// no-op when `allow_private` is true. Resolution failure is operational
168	/// (`Other`); a blocked address is a deliberate refusal (`Denied`).
169	pub(crate) async fn ssrf_check(url: &url::Url, allow_private: bool) -> Result<(), ToolError> {
170	    if allow_private {
171	        return Ok(());
172	    }
173	    let denied = |host: &str| ToolError::Denied {
174	        reason: format!(
175	            "host `{host}` resolves to a blocked (private/loopback/link-local) address"
176	        ),
177	    };
178	    match url.host() {
179	        Some(url::Host::Ipv4(ip)) => {
180	            if ip_blocked(IpAddr::V4(ip)) {
181	                return Err(denied(&ip.to_string()));
182	            }
183	        }
184	        Some(url::Host::Ipv6(ip)) => {
185	            if ip_blocked(IpAddr::V6(ip)) {
186	                return Err(denied(&ip.to_string()));
187	            }
188	        }
189	        Some(url::Host::Domain(host)) => {
190	            let port = url.port_or_known_default().unwrap_or(80);
191	            let addrs = tokio::net::lookup_host((host, port)).await.map_err(|e| {
192	                ToolError::Other(anyhow::anyhow!("DNS resolution failed for `{host}`: {e}"))
193	            })?;
194	            let mut any = false;
195	            for addr in addrs {
196	                any = true;
197	                if ip_blocked(addr.ip()) {
198	                    return Err(denied(host));
199	                }
200	            }
201	            if !any {
202	                return Err(ToolError::Other(anyhow::anyhow!(
203	                    "no addresses resolved for `{host}`"
204	                )));
205	            }
206	        }
207	        None => {
208	            return Err(ToolError::Denied {
209	                reason: "URL has no host".to_owned(),
210	            });
211	        }
212	    }
213	    Ok(())
214	}
