11	const DEFAULT_UA: &str = concat!("paigasus-helikon-tools/", env!("CARGO_PKG_VERSION"));
12	const DEFAULT_ENDPOINT: &str = "https://api.tavily.com/search";
13	const SNIPPET_CHARS: usize = 200;
14	
15	/// Tavily search API backend.
16	pub struct TavilyBackend {
17	    client: reqwest::Client,
18	    api_key: String,
19	    endpoint: String,
20	}
21	
22	impl TavilyBackend {
23	    /// Build a backend with an explicit API key.
24	    pub fn new(api_key: impl Into<String>) -> Result<Self, anyhow::Error> {
25	        let client = build_client(DEFAULT_UA, Duration::from_secs(30), true, None)
26	            .map_err(|e| anyhow::anyhow!("failed to build HTTP client: {e}"))?;
27	        Ok(Self {
28	            client,
29	            api_key: api_key.into(),
30	            endpoint: DEFAULT_ENDPOINT.to_owned(),
31	        })
32	    }
33	
34	    /// Build a backend, reading the key from `TAVILY_API_KEY`.
35	    pub fn from_env() -> Result<Self, anyhow::Error> {
36	        let key = std::env::var("TAVILY_API_KEY")
37	            .map_err(|_| anyhow::anyhow!("TAVILY_API_KEY is not set"))?;
38	        Self::new(key)
39	    }
40	
41	    #[cfg(test)]
42	    fn with_endpoint(api_key: impl Into<String>, endpoint: impl Into<String>) -> Self {
43	        Self {
44	            client: build_client(DEFAULT_UA, Duration::from_secs(30), true, None).unwrap(),
45	            api_key: api_key.into(),
46	            endpoint: endpoint.into(),
47	        }
48	    }
49	}
