51	#[async_trait]
52	impl SearchBackend for TavilyBackend {
53	    fn name(&self) -> &str {
54	        "tavily"
55	    }
56	
57	    async fn search(&self, query: &str, limit: usize) -> Result<Vec<SearchResult>, anyhow::Error> {
58	        let req_body = serde_json::json!({
59	            "api_key": self.api_key,
60	            "query": query,
61	            "max_results": limit,
62	        });
63	        let resp = self
64	            .client
65	            .post(&self.endpoint)
66	            .json(&req_body)
67	            .send()
68	            .await
69	            .map_err(|e| super::sanitize_err("tavily", &e))?;
70	        if !resp.status().is_success() {
71	            return Err(anyhow::anyhow!(
72	                "tavily request failed: HTTP {}",
73	                resp.status().as_u16()
74	            ));
75	        }
76	        let body: Value = resp
77	            .json()
78	            .await
79	            .map_err(|e| super::sanitize_err("tavily", &e))?;
80	        Ok(parse_tavily(&body, limit))
81	    }
82	}
83	
84	/// Map a Tavily response body to normalized results. Tavily returns a `content`
85	/// chunk per result; the snippet is that content truncated to [`SNIPPET_CHARS`].
86	fn parse_tavily(body: &Value, limit: usize) -> Vec<SearchResult> {
87	    body.get("results")
88	        .and_then(|r| r.as_array())
89	        .map(|arr| {
90	            arr.iter()
91	                .take(limit)
92	                .map(|item| {
93	                    let content = item
94	                        .get("content")
95	                        .and_then(|v| v.as_str())
96	                        .map(str::to_owned);
97	                    let snippet = content
98	                        .as_deref()
99	                        .map(|c| c.chars().take(SNIPPET_CHARS).collect::<String>())
100	                        .unwrap_or_default();
101	                    SearchResult::new(
102	                        item.get("title")
103	                            .and_then(|v| v.as_str())
104	                            .unwrap_or_default(),
105	                        item.get("url").and_then(|v| v.as_str()).unwrap_or_default(),
106	                        snippet,
107	                        content,
108	                    )
109	                })
110	                .collect()
111	        })
112	        .unwrap_or_default()
113	}
